from app import net


def test_fetch_returns_body(monkeypatch):
    class Resp:
        def __enter__(self):
            return self

        def __exit__(self, *exc):
            return False

        def read(self):
            return b"ok"

    monkeypatch.setattr(net.urllib.request, "urlopen", lambda url, timeout: Resp())
    assert net.fetch("http://example") == b"ok"


def _always_down(url):
    raise OSError("down")


def test_fetch_with_retry_succeeds_after_failures(monkeypatch):
    calls = []

    def flaky(url):
        calls.append(url)
        if len(calls) < 3:
            raise OSError("down")
        return b"ok"

    monkeypatch.setattr(net, "fetch", flaky)
    monkeypatch.setattr(net.time, "sleep", lambda s: None)
    assert net.fetch_with_retry("http://example") == b"ok"
    assert len(calls) == 3


def test_fetch_with_retry_default_attempt_count(monkeypatch):
    calls = []

    def down(url):
        calls.append(url)
        raise OSError("down")

    monkeypatch.setattr(net, "fetch", down)
    monkeypatch.setattr(net.time, "sleep", lambda s: None)
    try:
        net.fetch_with_retry("http://example")
    except OSError:
        pass
    else:
        raise AssertionError("expected OSError")
    assert len(calls) == 10


def test_fetch_with_retry_raises_after_exhaustion(monkeypatch):
    calls = []

    def down(url):
        calls.append(url)
        raise OSError("down")

    monkeypatch.setattr(net, "fetch", down)
    monkeypatch.setattr(net.time, "sleep", lambda s: None)
    try:
        net.fetch_with_retry("http://example", attempts=2)
    except OSError:
        pass
    else:
        raise AssertionError("expected OSError")
    assert len(calls) == 2


def test_fetch_with_retry_rejects_attempts_outside_range():
    for attempts in (0, 11):
        try:
            net.fetch_with_retry("http://example", attempts=attempts)
        except ValueError:
            pass
        else:
            raise AssertionError("expected ValueError")

